}b.dashboard {
  padding-top: 36px;
  padding-bottom: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.dashboard-btn {
  box-shadow: 0 2px 14px rgba(0,0,0,0.06);
  border-radius: 18px;
  font-size: 1.24rem;
  padding: 18px 20px;
  margin: 8px 0;
  background: var(--kavia-orange);
  color: #fff;
  border: none;
  outline: none;
  font-weight: 600;
  width: 160px;
  min-width: 120px;
  min-height: 100px;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: transform 0.12s, box-shadow 0.12s, opacity 0.16s;
  cursor: pointer;
}

.dashboard-btn:active,
.dashboard-btn:focus {
  transform: scale(0.98);
  box-shadow: 0 2px 22px #F76B8A33;
}

.dashboard-btn:hover {
  filter: brightness(1.07);
  opacity: 0.98;
}

